def run(number):
    p = next(Path("test_data").glob(str(number) + "*.docx"))
    t = InputLayer()._extract_from_docx_content(p.read_bytes())
    with contextlib.redirect_stdout(io.StringIO()):
        return engine.review_contract_v2(t, "technology", use_llm=False, include_low_risk=True,
            profile=UserRiskProfile(user_identity="甲方/被许可方"))
